package io.tenvyr.control.engine;

import com.fasterxml.jackson.databind.node.ObjectNode;
import io.tenvyr.platform.*;
import java.time.*;
import java.util.*;
import static io.tenvyr.control.engine.EngineFacts.*;

public final class DispatchOutboxService {
  public record Disposition(String outcome,String executionId){}public record Recovery(int dispatched,List<String> terminalFailures,int retryableFailures){}
  private final Db db;private final AgentAdapter adapter;private final AgentTransportConfig config;private final EngineAuthority authority;
  public DispatchOutboxService(Db db,AgentAdapter adapter,AgentTransportConfig config,EngineAuthority authority){this.db=db;this.adapter=adapter;this.config=config;this.authority=authority;}
  public Disposition dispatchNext()throws Exception{ObjectNode row=claim(null);return row==null?new Disposition("idle",null):dispatch(row);}public Disposition dispatchAttempt(String id)throws Exception{ObjectNode row=claim(id);return row==null?new Disposition("idle",null):dispatch(row);}
  private ObjectNode claim(String attemptId){return db.transaction(tx->{Instant now=Instant.now();String sql="SELECT o.* FROM dispatch_outbox o JOIN step_attempts a ON a.id=o.\"stepAttemptId\" WHERE ((o.status='PENDING' AND o.\"nextDispatchAt\"<=?) OR (o.status='LEASED' AND o.\"leaseExpiresAt\"<=?)) AND a.status NOT IN "+ATTEMPT_TERMINAL_SQL+" AND EXISTS (SELECT 1 FROM executions e WHERE e.id=a.\"executionId\" AND e.status NOT IN "+EXECUTION_TERMINAL_SQL+")";List<Object> args=new ArrayList<>(List.of(now,now));if(attemptId!=null){sql+=" AND o.\"stepAttemptId\"=?";args.add(attemptId);}sql+=" ORDER BY o.\"nextDispatchAt\",o.id LIMIT 1 FOR UPDATE OF o SKIP LOCKED";ObjectNode row=tx.one(sql,args.toArray());if(row==null)return null;return tx.update("dispatch_outbox",row.path("id").asText(),Json.object("status","LEASED","leaseExpiresAt",now.plusSeconds(60).toString(),"leaseToken",UUID.randomUUID().toString(),"dispatchCount",row.path("dispatchCount").asInt()+1));});}
  private Disposition dispatch(ObjectNode row)throws Exception{try{ObjectNode invocation=Protocol.invocation(row.get("invocation"));ObjectNode attempt=db.one("SELECT * FROM step_attempts WHERE id=?",row.path("stepAttemptId").asText());if(attempt==null)throw new AdapterError("EXECUTOR_SNAPSHOT_INVALID",false,"Dispatch references missing attempt");ObjectNode pinned=config.frozenDescriptor(attempt.get("executorSnapshot"));if(pinned.has("connection")){ObjectNode connection=db.one("SELECT \"statusState\" FROM runtime_connections WHERE \"connectionId\"=?",pinned.path("connection").path("connectionId").asText());if(connection==null||connection.path("statusState").asText().equals("REVOKED"))throw new AdapterError("EXECUTOR_CONNECTION_REVOKED",false,"Runtime connection is revoked or missing");}ObjectNode receipt=adapter.invoke(invocation,pinned);markDispatched(row,receipt);return new Disposition("dispatched",null);}catch(Exception error){if(error instanceof AdapterError adapterError&&!adapterError.retryable){return new Disposition("terminal_failure",failNonRetryable(row,adapterError));}db.execute("UPDATE dispatch_outbox SET status='PENDING',\"leaseExpiresAt\"=NULL,\"leaseToken\"=NULL,\"nextDispatchAt\"=?,error=? WHERE id=? AND status='LEASED' AND \"leaseToken\"=?",Instant.now().plusSeconds(1),message(error),row.path("id").asText(),row.path("leaseToken").asText());throw error;}}
  private String failNonRetryable(ObjectNode row,AdapterError error){String id=row.path("invocation").path("executionId").asText();db.transaction(tx->{ObjectNode attempt=tx.one("SELECT * FROM step_attempts WHERE id=? FOR UPDATE",row.path("stepAttemptId").asText());if(attempt==null)return null;int leased=tx.execute("UPDATE dispatch_outbox SET status='FAILED',\"leaseExpiresAt\"=NULL,\"leaseToken\"=NULL,error=? WHERE id=? AND status='LEASED' AND \"leaseToken\"=?",message(error),row.path("id").asText(),row.path("leaseToken").asText());if(leased!=1)return null;String failure="Non-retryable dispatch failure: "+message(error);Instant now=Instant.now();int changed=tx.execute("UPDATE step_attempts SET status='FAILED',\"terminalAt\"=?,result=NULL,error=?,\"terminationReason\"=? WHERE id=? AND status NOT IN "+ATTEMPT_TERMINAL_SQL,now,failure,failure,attempt.path("id").asText());if(changed!=1)return null;authority.releaseBudget(tx.connection(),attempt.path("invocationId").asText(),"non-retryable dispatch failure");ObjectNode logical=tx.one("SELECT * FROM step_executions WHERE id=? FOR UPDATE",attempt.path("logicalStepId").asText());if(logical==null||TERMINAL_STEP.contains(logical.path("status").asText()))return null;ObjectNode execution=tx.one("SELECT * FROM executions WHERE id=? FOR UPDATE",attempt.path("executionId").asText());ObjectNode revision=tx.one("SELECT * FROM execution_plan_revisions WHERE id=?",attempt.path("planRevisionId").asText());ObjectNode step=revision==null?null:step(revision.path("plan"),logical.path("stepId").asText());if(execution!=null)ExecutionService.settleFailure(tx,execution,logical,step,attempt,failure,now);return null;});return id;}
  private void markDispatched(ObjectNode row,ObjectNode receipt){db.transaction(tx->{ObjectNode attempt=tx.one("SELECT * FROM step_attempts WHERE id=? FOR UPDATE",row.path("stepAttemptId").asText());if(attempt==null||TERMINAL_ATTEMPT.contains(attempt.path("status").asText()))return null;int updated=tx.execute("UPDATE dispatch_outbox SET status='DISPATCHED',\"leaseExpiresAt\"=NULL,\"leaseToken\"=NULL,receipt=?,error=NULL WHERE id=? AND status='LEASED' AND \"leaseToken\"=?",receipt,row.path("id").asText(),row.path("leaseToken").asText());if(updated==1&&attempt.path("status").asText().equals("CREATED"))tx.update("step_attempts",attempt.path("id").asText(),Json.object("status","DISPATCHED","dispatchedAt",Instant.now().toString()));return null;});}
  public Recovery recover(){int dispatched=0,retryable=0;Set<String> terminal=new LinkedHashSet<>();for(int i=0;i<100;i++){ObjectNode row=claim(null);if(row==null)break;try{Disposition outcome=dispatch(row);if(outcome.outcome.equals("dispatched"))dispatched++;else if(outcome.outcome.equals("terminal_failure"))terminal.add(outcome.executionId);}catch(Exception e){retryable++;}}return new Recovery(dispatched,List.copyOf(terminal),retryable);}
  public ObjectNode notifyCancel(String executionId,String reason){int notified=0,unsupported=0,unreachable=0;List<ObjectNode> rows=db.query("SELECT o.*,a.\"executorSnapshot\" FROM dispatch_outbox o JOIN step_attempts a ON a.id=o.\"stepAttemptId\" WHERE a.\"executionId\"=? AND a.status='CANCELLED' AND o.status='COMPLETED' AND o.receipt IS NOT NULL AND o.error IS NULL",executionId);for(ObjectNode row:rows){String outcome;try{ObjectNode snapshot=config.frozenDescriptor(row.get("executorSnapshot"));if(!snapshot.path("capabilities").path("cancel").asBoolean()){outcome="cancel notification: unsupported (executor cannot cancel)";unsupported++;}else{ObjectNode invocation=(ObjectNode)row.get("invocation"),receipt=(ObjectNode)row.get("receipt");ObjectNode request=Json.object("invocationId",invocation.get("invocationId"),"executionId",executionId,"reason",reason);if(receipt.has("dispatchId"))request.set("dispatchId",receipt.get("dispatchId"));ObjectNode result=adapter.cancel(request);if(result.path("delivered").asBoolean()){outcome="cancel notification: delivered";notified++;}else{outcome="cancel notification: unreachable (executor did not acknowledge)";unreachable++;}}}catch(Exception error){outcome="cancel notification: unreachable ("+message(error)+")";unreachable++;}db.update("dispatch_outbox",row.path("id").asText(),Json.object("error",outcome));}return Json.object("notified",notified,"unsupported",unsupported,"unreachable",unreachable);}
}
